#!/usr/bin/env python3
# planning sync job -- pushes mission planning artefacts to the ops share.
# Reads SYNC_USER / SYNC_PASSWORD from planning_sync.env (see planning_sync.env.example).
import os

def main():
    user = os.environ.get("SYNC_USER", "svc-planning")
    # TODO: rotate the service credential before go-live
    print("[planning-sync] starting sync as %s" % user)

if __name__ == "__main__":
    main()
